(function(){
 if(committee)return;
 let report=null,busy=false,selected=new Set();
 const panel=document.createElement('section');panel.className='card attendance-import';
 panel.innerHTML='<details><summary>Actualizar desde la planilla</summary><p class="helper">Selecciona el mes, actualiza la planilla y aplica los cambios.</p><div class="transfer-actions"><button type="button" class="button outline" id="attendance-google">Actualizar desde Google Sheets</button><button type="button" class="button outline" id="attendance-upload">Cargar Excel actualizado</button><input id="attendance-file" type="file" accept=".xlsx" hidden></div><p id="attendance-connection" class="helper" hidden></p><p id="attendance-status" class="helper" role="status"></p><div id="attendance-result"></div></details>';
 document.querySelector('.editor-layout').before(panel);
 const google=$('attendance-google'),upload=$('attendance-upload'),file=$('attendance-file'),status=$('attendance-status'),result=$('attendance-result');
 const names={changed:'Cambios detectados',new:'Nuevo borrador',unchanged:'Sin cambios',transferred:'Transferencia registrada',reference:'Horario habitual',blocked:'Revisar datos',applied:'Actualizado',failed:'No aplicado'};
 const eligible=row=>['changed','new'].includes(row.state);
 const source=e=>[e.date,e.sheet,e.cell||(e.row?'fila '+e.row:'')].filter(Boolean).join(' · ');
 const amount=(value,missing='Pendiente')=>value==null?missing:money(value);
 const eventLabel=e=>({aseoExtraDays:'Jornada extra ASEO con 50%',replacementDays:'Días adicionales',overtimeHours:'Horas de cobertura','honorarios-day':'Jornada de honorarios',worked:'Asistencia',absent:'Ausencia',vacation:'Vacaciones pagadas'}[e.credit||e.kind]||e.credit||e.kind);
 function updateApply(){
  const button=$('attendance-apply');if(button){button.disabled=busy||!selected.size||!report?.token;button.textContent='Aplicar '+selected.size+' cambio'+(selected.size===1?'':'s')+' y recalcular';}
  result.querySelectorAll('[data-sync-worker]').forEach(box=>{box.disabled=busy||!report?.token||!report.rows.some(r=>r.worker===box.dataset.syncWorker&&eligible(r));});
  const all=$('attendance-select-all');if(all&&report){const ids=report.rows.filter(eligible).map(r=>r.worker);all.disabled=busy||!ids.length||!report.token;all.checked=ids.length>0&&ids.every(id=>selected.has(id));all.indeterminate=selected.size>0&&!all.checked;}
 }
 function render(){
  if(!report)return;
  const changed=report.rows.filter(eligible).length,locked=report.rows.filter(r=>r.state==='transferred').length,blocked=report.rows.filter(r=>r.state==='blocked').length;
  result.innerHTML='<p class="helper">'+escapeHtml(periodLabel(report.period))+' · Fuente: '+(report.source==='google'?'Google Sheets':'Excel cargado')+' · Leído: '+escapeHtml(new Date(report.readAt).toLocaleString('es-CL',{dateStyle:'short',timeStyle:'short',timeZone:'America/Santiago'}))+'</p><div class="sync-summary">'+changed+' con cambios · '+locked+' transferidos bloqueados · '+blocked+' por revisar</div><p class="helper">Selecciona los registros que vas a actualizar. Los anticipos guardados se conservan.</p>'+
   '<div class="attendance-table-wrap"><table class="attendance-table sync-table"><thead><tr><th><input type="checkbox" id="attendance-select-all" aria-label="Seleccionar todos los cambios" '+(!changed?'disabled':'')+'></th><th>Trabajador</th><th>Cambios de asistencia</th><th>Transferencia guardada</th><th>Transferencia recalculada</th><th>Estado y origen</th></tr></thead><tbody>'+report.rows.map(row=>'<tr><td><input type="checkbox" data-sync-worker="'+escapeHtml(row.worker)+'" aria-label="Seleccionar '+escapeHtml(row.name)+'" '+(selected.has(row.worker)?'checked ':'')+(!eligible(row)?'disabled':'')+'></td><td><strong>'+escapeHtml(row.name)+'</strong><small>'+escapeHtml(row.role)+'</small></td><td>'+(row.changes.length?row.changes.map(c=>'<div>'+escapeHtml(c.label)+': <strong>'+(c.before==null?'—':c.before)+' → '+c.after+'</strong></div>').join(''):'<span class="sync-muted">'+(row.state==='reference'?'Se mantienen las novedades manuales.':row.state==='changed'?'Actualización del cálculo':'Sin cambios aplicables')+'</span>')+'</td><td>'+escapeHtml(amount(row.currentAmount,row.currentRevision?'Pendiente':'Sin borrador'))+'</td><td>'+escapeHtml(amount(row.nextAmount))+'</td><td><span class="badge">'+escapeHtml(names[row.state]||row.state)+'</span><small>'+escapeHtml(row.message)+'</small>'+(row.pending?.length?'<small>'+escapeHtml(row.pending.join(' '))+'</small>':'')+'<details><summary>Ver origen</summary><p>Días base: '+row.worked+' · Ausencias: '+row.absent+' · Vacaciones pagadas: '+row.vacation+' · Adicionales: '+row.replacementDays+' · Horas: '+row.overtimeHours+' · Jornadas extra ASEO con 50%: '+(row.aseoExtraDays||0)+'</p>'+(row.scheduleReference?'<p>'+escapeHtml(row.scheduleReference)+'</p>':'')+row.events.map(e=>'<p>'+escapeHtml(source(e))+' · '+escapeHtml(eventLabel(e))+(e.amount?' · '+e.amount:'')+'</p>').join('')+row.issues.map(e=>'<p>'+escapeHtml(source(e))+' · '+escapeHtml(e.message)+'</p>').join('')+'</details>'+(!['transferred','blocked'].includes(row.state)?'<button type="button" class="button outline" data-attendance-use="'+escapeHtml(row.worker)+'">Abrir formulario</button>':'')+'</td></tr>').join('')+'</tbody></table></div><div class="sync-apply"><button type="button" class="button primary" id="attendance-apply">Aplicar cambios y recalcular</button><small>Solo se guardan las personas seleccionadas. Las transferencias registradas permanecen bloqueadas.</small></div>'+
   (report.issues.length?'<details class="attendance-issues"><summary>'+report.issues.length+' observaciones de la planilla</summary>'+report.issues.map(e=>'<p>'+escapeHtml(source(e))+' · '+escapeHtml(e.message)+'</p>').join('')+'</details>':'');updateApply();
 }
 async function readSource(body){
  if(busy)return;const period=$('period').value;if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(period)){status.textContent='Selecciona el período de liquidación.';return;}
  busy=true;google.disabled=upload.disabled=true;status.textContent='Actualizando asistencia…';result.replaceChildren();report=null;selected.clear();
  try{const next=await api(body?'api/attendance/preview':'api/attendance/preview?period='+encodeURIComponent(period),body?{...body,period}:undefined);if($('period').value!==period){status.textContent='Actualiza la planilla del período seleccionado.';return;}report=next;selected=new Set(report.rows.filter(r=>r.state==='changed').map(r=>r.worker));await refreshShared();render();status.textContent=report.rows.some(eligible)?'Pulsa Aplicar para guardar los registros seleccionados y recalcular.':'Sin cambios pendientes.';}
  catch(e){status.textContent=e.message;}finally{busy=false;google.disabled=upload.disabled=false;updateApply();}
 }
 google.addEventListener('click',()=>readSource());upload.addEventListener('click',()=>file.click());
 file.addEventListener('change',async()=>{const chosen=file.files[0];if(!chosen)return;if(chosen.size>2*1024*1024){status.textContent='Carga un archivo Excel de hasta 2 MB.';file.value='';return;}try{const bytes=new Uint8Array(await chosen.arrayBuffer());let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);await readSource({file:btoa(binary)});}catch{status.textContent='No se pudo leer el archivo.';}finally{file.value='';}});
 result.addEventListener('change',event=>{if(busy||!report)return;if(event.target.id==='attendance-select-all'){selected=new Set(event.target.checked?report.rows.filter(eligible).map(r=>r.worker):[]);result.querySelectorAll('[data-sync-worker]').forEach(box=>box.checked=selected.has(box.dataset.syncWorker));}else if(event.target.matches('[data-sync-worker]')){const id=event.target.dataset.syncWorker;if(event.target.checked)selected.add(id);else selected.delete(id);}updateApply();});
 result.addEventListener('click',async event=>{
  if(busy||!report)return;
  if(report.period!==$('period').value){status.textContent='Actualiza la planilla del período seleccionado.';return;}
  if(event.target.closest('#attendance-apply')){
   if(!selected.size||!report.token)return;const formData=read();if(Payroll.fields.some(key=>Number(formData[key]||0)!==Number(viewRecord?.data?.[key]||0))){status.textContent='Guarda los cambios del formulario antes de actualizar la planilla.';return;}busy=true;google.disabled=upload.disabled=true;updateApply();status.textContent='Guardando y recalculando…';
   try{const response=await api('api/attendance/apply',{token:report.token,workers:[...selected]});let updated=0,failed=0;for(const item of response.results){const row=report.rows.find(r=>r.worker===item.worker);if(item.state==='failed'){failed++;row.state='failed';row.message=item.error;}else{updated++;row.state='applied';row.message=item.state==='already-applied'?'Esta revisión ya estaba guardada.':'Borrador recalculado y guardado.';}}selected.clear();report.token=null;await refreshShared();loadRecord();render();status.textContent=updated+' registros actualizados.'+(failed?' '+failed+' sin guardar. Corrige los errores y actualiza la planilla.':'');}
   catch(e){status.textContent=e.message;}finally{busy=false;google.disabled=upload.disabled=false;updateApply();}return;
  }
  const button=event.target.closest('[data-attendance-use]');if(!button)return;const row=report.rows.find(r=>r.worker===button.dataset.attendanceUse);if(!row||['transferred','blocked'].includes(row.state))return;
  if(!storageReady){status.textContent='Espera a que termine la carga de los registros.';return;}if(drafts[row.worker+'_'+report.period]?.status==='transferred'){status.textContent='Este borrador ya tiene transferencia registrada.';return;}
  $('worker').value=row.worker;loadRecord();if(row.input&&row.state!=='applied')for(const key of Payroll.fields.filter(key=>key!=='advance'))$(key).value=row.input[key];update();panel.querySelector('details').open=false;$('payroll-form').scrollIntoView({behavior:'smooth',block:'start'});
 });
 $('period').addEventListener('change',()=>{report=null;selected.clear();result.replaceChildren();status.textContent='';});
 api('api/attendance/connection').then(connection=>{const message=$('attendance-connection');message.textContent=connection.configured?'':'Configura la conexión con Google Sheets o carga un archivo Excel.';message.hidden=connection.configured;}).catch(()=>{const message=$('attendance-connection');message.textContent='No se pudo comprobar la conexión con Google.';message.hidden=false;});
})();